'use strict';
(()=>{
 const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',entry:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 11h16 M8 15h3 M8 18h7',income:'M4 20V4 M4 20h17 M8 16l4-6 4 3 5-8',assets:'M3 7h18v14H3z M3 7l9-4 9 4 M16 12h5v5h-5z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};
 const icon=key=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[key]||paths.assets}"/></svg>`;
 for(const a of document.querySelectorAll('nav a[data-route]')){const text=a.querySelector('span').textContent;a.innerHTML=icon(a.dataset.route)+'<span>'+escapeHTML(text)+'</span>';}
 document.querySelector('.logo').innerHTML=icon('assets');
 const bar=document.createElement('div');bar.className='app-topbar';bar.innerHTML='<div class="app-breadcrumb">家有数 <span>/</span> 家庭收入与资产</div><div class="app-topbar-tools"></div>';document.querySelector('main').prepend(bar);const session=document.querySelector('.session-bar');if(session)bar.lastElementChild.append(session);
 const toggle=document.createElement('button');toggle.className='theme-toggle';toggle.type='button';bar.lastElementChild.prepend(toggle);function theme(value){document.documentElement.dataset.theme=value;toggle.textContent=value==='dark'?'☀':'☾';toggle.setAttribute('aria-label',value==='dark'?'切换浅色主题':'切换深色主题');toggle.title=toggle.getAttribute('aria-label');}let saved='dark';try{saved=localStorage.getItem('family-theme')||'dark';}catch{}theme(saved==='light'?'light':'dark');toggle.onclick=()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';theme(next);try{localStorage.setItem('family-theme',next);}catch{}};
 const definitions={assetValue:'所选结束日以前最近的资产记录：可能是账户余额与市值合计，也可能是单独导入的历史家庭总额。',deltaValue:'期末资产减去开始日前最近的资产参考值。账户范围变动也会影响金额，不等于赚了多少钱。',incomeValue:'所选期间已经录入的家庭收入。内部转账、初始余额和单纯的估值上涨不算收入。',reportIncomeValue:'按所选日期及成员汇总已录收入，内部转账不计入；历史汇总只在统计范围覆盖其完整期间时计入，不自动按天拆分。'};
 const metricDefinitions={incomeCents:'本月已录收入合计，不含内部转账。',assetsCents:'各账户余额 / 市值的人民币合计，可能沿用旧盘点。',deltaCents:'与月初以前最近的资产参考值比较；缺少期初时不计算。'};
 function explain(container,text){if(!container||container.querySelector('.metric-definition'))return;const p=document.createElement('small');p.className='metric-definition';p.textContent=text;container.append(p);}
 function apply(){for(const [id,text]of Object.entries(definitions)){const value=$(id);if(value)explain(value.closest('article')||value.parentElement,text);}for(const a of $('monthSummary')?.children||[])explain(a,metricDefinitions[a.dataset.metric]||'金额来自当前已保存的账本记录。');for(const a of $('temporaryMetrics')?.children||[]){const label=a.querySelector('span')?.textContent||'',key=label.includes('收入')?'incomeCents':label.includes('变化')?'deltaCents':'assetsCents';explain(a,metricDefinitions[key]);}
  for(const [id,key]of [['assetValue','assets'],['deltaValue','income'],['incomeValue','entry']]){const card=$(id)?.closest('article');if(card&&!card.querySelector('.metric-glyph')){const glyph=document.createElement('span');glyph.className='metric-glyph';glyph.innerHTML=icon(key);card.append(glyph);}}
 }
 const observer=new MutationObserver(()=>apply());for(const id of ['monthSummary','temporaryMetrics'])if($(id))observer.observe($(id),{childList:true});document.addEventListener('family-ledger-ready',apply);document.addEventListener('family-app-ready',apply);window.FamilyMetricHelp={apply};apply();
})();
